    "De zaak van de week is gesloten, {0}. Deel het resultaat, dan weet de rest van het bureau het ook.": "সপ্তাহের কেস বন্ধ হলো, {0}। ফলটা শেয়ার করুন, তাহলে দপ্তরের বাকিরাও জানবে।",
