    "Combineer {1|one:aanwijzing|other:aanwijzingen} {0} met de spelregel over het slachtoffer.": "সূত্র {0} আর নিহতের ঘরের নিয়ম একসঙ্গে মিলিয়ে দেখুন।",
    "De spelregel over het slachtoffer dwingt dit af.": "নিহতের ঘরের নিয়মই এটা ঠিক করে দেয়।",
    "Aanwijzing {0} beperkt de opties. Streep vakjes weg die er niet aan voldoen.": "সূত্র {0} বিকল্প কমিয়ে দেয়। যে খোপগুলো এর সঙ্গে মেলে না, সেগুলো কেটে দিন।",
