    "De zaak van vandaag heet “{0}”. Een paar minuten, meer vraag ik niet.": "আজকের কেসের নাম “{0}”। কয়েক মিনিট, এর বেশি কিছু চাই না।",
    "Nieuw dossier: “{0}”. Plaats delict: {1}.": "নতুন ফাইল: “{0}”। ঘটনাস্থল: {1}।",
